//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_CAN_FILTER_OP(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.CAN_FILTER_OP
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.CAN_FILTER_REPLACE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.CAN_FILTER_OP
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.CAN_FILTER_REPLACE, dec)
	})
}
